# Pointwise semantics: at every instant the active city must be
# unchanged outside the correction window and 'Boise' inside it.
def city_at(h, t):
    hits = [r["city"] for r in h if r["valid_from"] <= t < r["valid_to"]]
    assert len(hits) == 1, f"{t}: expected exactly one active version, got {hits}"
    return hits[0]

bounds = {EPOCH}
for r in before_snapshot + history:
    bounds.update((r["valid_from"], r["valid_to"]))
bounds.update((corr_from, corr_to))
for t in sorted(bounds):
    if not (EPOCH <= t < MAX_DATE):
        continue
    before_city = city_at(before_snapshot, t)
    after_city = city_at(history, t)
    if corr_from <= t < corr_to:
        assert after_city == "Boise", f"{t}: expected corrected city, got {after_city}"
    else:
        assert after_city == before_city, f"{t}: history changed outside window"

